def compute(vars):
    operating_cash_flow = vars["v1"]
    investing_cash_flow = vars["v2"]
    investing_cash_used = abs(investing_cash_flow)

    if investing_cash_used == 0:
        return None

    ratio = operating_cash_flow / investing_cash_used
    return {
        "value": ratio,
        "trace": {
            "operating_cash_flow": operating_cash_flow,
            "investing_cash_flow": investing_cash_flow,
            "investing_cash_used": investing_cash_used,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
